258	            continue;
259	        } else if let Some(elem) = elem.to_packed::<AssetElem>() {
260	            items.push(Child::Asset(elem));
261	            elem.path.as_ref()
262	        } else if let Some(elem) = elem.to_packed::<DocumentElem>() {
263	            items.push(Child::Document(elem, *styles, locator.next(&elem.span())));
264	            elem.path.as_ref()
265	        } else {
266	            errors.push(error!(
267	                elem.span(), "{} is not allowed at the top-level in bundle export",
268	                elem.func().name();
269	                hint: "try wrapping the content in a `document` instead";
270	            ));
271	            continue;
272	        };
273	
274	        match seen.entry(path) {
275	            Entry::Vacant(entry) => {
276	                entry.insert(elem.span());
277	            }
278	            Entry::Occupied(entry) => {
279	                engine.sink.delayed_error(error!(
280	                    elem.span(), "path `{}` occurs multiple times in the bundle",
281	                    path.get_without_slash();
282	                    hint: "{} paths must be unique in the bundle",
283	                    elem.func().name();
284	                    hint[*entry.get()]: "path is already in use here";
285	                ));
286	            }
287	        }
288	    }
289	
290	    if !errors.is_empty() {
291	        return Err(errors);
292	    }
293	
294	    Ok(items)
295	}
