42	/// In the `bundle` target, Typst can emit multiple documents and assets from a
43	/// single Typst project.
44	///
45	/// The `Bundle` is the output of compilation and is to the `bundle` output
46	/// format what the `PagedDocument` is to `pdf`, `png`, and `svg` outputs.
47	#[derive(Debug, Clone)]
48	pub struct Bundle {
49	    /// The files in the bundle.
50	    pub files: Arc<IndexMap<VirtualPath, BundleFile, FxBuildHasher>>,
51	    /// An introspector for the whole bundle.
52	    ///
53	    /// The whole bundle is subject to one large introspection loop (as opposed
54	    /// to each document iterating separately). They can introspect each other
55	    /// and all contribute to this one introspector.
56	    pub introspector: Arc<BundleIntrospector>,
57	}
58	
59	impl Output for Bundle {
60	    fn introspector(&self) -> &dyn Introspector {
61	        self.introspector.as_ref()
62	    }
63	
64	    fn target() -> Target {
65	        Target::Bundle
66	    }
67	
68	    fn create(
69	        engine: &mut Engine,
70	        content: &Content,
71	        styles: StyleChain,
72	    ) -> SourceResult<Self> {
73	        bundle(engine, content, styles)
74	    }
75	}
76	
77	/// A single file in the bundle.
78	#[derive(Debug, Clone)]
79	pub enum BundleFile {
80	    /// A document in one of the supported output formats, resulting from a
81	    /// `document` element.
82	    Document(BundleDocument),
83	    /// Raw file data, resulting from an `asset` element.
84	    Asset(Bytes),
85	}
86	
87	/// A document in one of the supported output formats, resulting from a
88	/// `document` element.
89	#[derive(Debug, Clone)]
90	pub enum BundleDocument {
91	    /// A document in one of the paged formats.
92	    Paged(Box<PagedDocument>, PagedExtras),
93	    /// A document in the HTML format.
94	    Html(Box<HtmlDocument>),
95	}
96	
97	impl Document for BundleDocument {
98	    fn info(&self) -> &DocumentInfo {
99	        match self {
100	            BundleDocument::Paged(doc, _) => doc.info(),
101	            BundleDocument::Html(doc) => doc.info(),
102	        }
103	    }
104	
105	    fn options(&self) -> &DocumentFormatOptions {
106	        match self {
107	            BundleDocument::Paged(doc, _) => doc.options(),
108	            BundleDocument::Html(doc) => doc.options(),
109	        }
110	    }
111	}
112	
113	/// Extra data relevant for exporting a paged document in a bundle.
114	#[derive(Debug, Clone, Hash)]
115	pub struct PagedExtras {
116	    /// The format to export in.
117	    pub format: PagedFormat,
118	    /// Named anchors that should be exported, so that cross-document links can
119	    /// jump to a precise location.
120	    ///
121	    /// Not all export targets support this (e.g. PNG), in which case it can
122	    /// simply be ignored.
123	    pub anchors: Vec<(Location, EcoString)>,
124	}
125	
126	/// Produces a bundle from content.
127	///
128	/// This first performs root-level bundle realization and then compiles the
129	/// individual documents (in parallel).
130	#[typst_macros::time]
131	pub fn bundle(
132	    engine: &mut Engine,
133	    content: &Content,
134	    styles: StyleChain,
135	) -> SourceResult<Bundle> {
136	    bundle_impl(
137	        engine.world,
138	        engine.library,
139	        engine.introspector.into_raw(),
140	        engine.traced,
141	        TrackedMut::reborrow_mut(&mut engine.sink),
142	        engine.route.track(),
143	        content,
144	        styles,
145	    )
146	}
147	
148	/// The internal implementation of `bundle`.
149	#[comemo::memoize]
150	#[expect(clippy::too_many_arguments)]
151	fn bundle_impl(
152	    world: Tracked<dyn World + '_>,
153	    library: &LazyHash<Library>,
154	    introspector: Tracked<dyn Introspector + '_>,
155	    traced: Tracked<Traced>,
156	    sink: TrackedMut<Sink>,
157	    route: Tracked<Route>,
158	    content: &Content,
159	    styles: StyleChain,
160	) -> SourceResult<Bundle> {
161	    let introspector = Protected::from_raw(introspector);
162	    let mut locator = Locator::root().split();
163	    let mut engine = Engine {
164	        library,
165	        world,
166	        introspector,
167	        traced,
168	        sink,
169	        route: Route::extend(route).unnested(),
170	    };
171	
172	    // Mark the external styles as "outside" so that they are valid at the page
173	    // level.
174	    let styles = styles.to_map().outside();
175	    let styles = StyleChain::new(&styles);
176	
177	    let arenas = Arenas::default();
178	    let children = (engine.library.routines.realize)(
179	        RealizationKind::Bundle,
180	        &mut engine,
181	        &mut locator,
182	        &arenas,
183	        content,
184	        styles,
185	    )?;
186	
187	    let children = collect(&children, &mut engine, &mut locator)?;
188	
189	    let mut items = engine
190	        .parallelize(children, |engine, child| -> SourceResult<_> {
191	            Ok(match child {
192	                Child::Tag(tag) => Item::Tag(tag.clone()),
193	                Child::Asset(asset) => Item::Asset(
194	                    asset.path.clone().into_inner(),
195	                    asset.data.0.clone(),
196	                    asset.location().unwrap(),
197	                ),
198	                Child::Document(document, styles, locator) => Item::Document(
199	                    document.path.clone().into_inner(),
200	                    compile_document(engine, document, styles, locator)?,
201	                    document.location().unwrap(),
202	                ),
203	            })
204	        })
205	        .collect_combined_result::<Vec<_>>()?;
206	
207	    let mut introspector = BundleIntrospector::new(&items);
208	    let targets = introspector.link_targets();
209	    let anchors = crate::link::create_link_anchors(&mut items, &targets);
210	    introspector.set_anchors(anchors);
211	
212	    let mut files = IndexMap::default();
213	    for item in items {
214	        match item {
215	            Item::Tag(_) => {}
216	            Item::Asset(path, bytes, _) => {
217	                files.insert(path, BundleFile::Asset(bytes));
218	            }
219	            Item::Document(path, doc, _) => {
220	                files.insert(path, BundleFile::Document(doc));
221	            }
222	        }
223	    }
224	
225	    Ok(Bundle {
226	        files: Arc::new(files),
227	        introspector: Arc::new(introspector),
228	    })
229	}
230	
231	/// Something that can result from bundle realization.
232	enum Child<'a> {
233	    Tag(&'a Tag),
234	    Asset(&'a Packed<AssetElem>),
235	    Document(&'a Packed<DocumentElem>, StyleChain<'a>, Locator<'a>),
236	}
237	
238	/// The processed version of a [`Child`].
239	enum Item {
240	    Tag(Tag),
241	    Asset(VirtualPath, Bytes, Location),
242	    Document(VirtualPath, BundleDocument, Location),
243	}
244	
245	/// Collects all documents and assets in the bundle.
246	fn collect<'a>(
247	    children: &'a [Pair<'a>],
248	    engine: &mut Engine,
249	    locator: &mut SplitLocator<'a>,
250	) -> SourceResult<Vec<Child<'a>>> {
251	    let mut items = Vec::new();
252	    let mut errors = EcoVec::new();
253	    let mut seen = FxHashMap::default();
254	
255	    for (elem, styles) in children {
256	        let path = if let Some(elem) = elem.to_packed::<TagElem>() {
257	            items.push(Child::Tag(&elem.tag));
258	            continue;
259	        } else if let Some(elem) = elem.to_packed::<AssetElem>() {
260	            items.push(Child::Asset(elem));
261	            elem.path.as_ref()
262	        } else if let Some(elem) = elem.to_packed::<DocumentElem>() {
263	            items.push(Child::Document(elem, *styles, locator.next(&elem.span())));
264	            elem.path.as_ref()
265	        } else {
266	            errors.push(error!(
267	                elem.span(), "{} is not allowed at the top-level in bundle export",
268	                elem.func().name();
269	                hint: "try wrapping the content in a `document` instead";
270	            ));
271	            continue;
272	        };
273	
274	        match seen.entry(path) {
275	            Entry::Vacant(entry) => {
276	                entry.insert(elem.span());
277	            }
278	            Entry::Occupied(entry) => {
279	                engine.sink.delayed_error(error!(
280	                    elem.span(), "path `{}` occurs multiple times in the bundle",
281	                    path.get_without_slash();
282	                    hint: "{} paths must be unique in the bundle",
283	                    elem.func().name();
284	                    hint[*entry.get()]: "path is already in use here";
285	                ));
286	            }
287	        }
288	    }
289	
290	    if !errors.is_empty() {
291	        return Err(errors);
292	    }
293	
294	    Ok(items)
295	}
296	
297	/// Compiles a single document.
298	fn compile_document<'a>(
299	    engine: &mut Engine,
300	    document: &'a Packed<DocumentElem>,
301	    styles: StyleChain<'a>,
302	    locator: Locator<'a>,
303	) -> SourceResult<BundleDocument> {
304	    let format = document.determine_format(styles).at(document.span())?;
305	    let target = TargetElem::target.set(format.target()).wrap();
306	    let styles = styles.chain(&target);
307	    Ok(match format {
308	        DocumentFormat::Paged(format) => {
309	            let doc = typst_layout::layout_document_for_bundle(
310	                engine,
311	                &document.body,
312	                locator,
313	                styles,
314	            )?;
315	
316	            let num_pages = doc.pages().len();
317	            if num_pages != 1 && matches!(format, PagedFormat::Png | PagedFormat::Svg) {
318	                engine.sink.delayed_error(error!(
319	                    document.span(),
320	                    "expected document to have a single page";
321	                    hint: "the document resulted in {num_pages} pages";
322	                    hint: "documents exported to an image format only support a single page";
323	                ));
324	            }
325	
326	            BundleDocument::Paged(
327	                Box::new(doc),
328	                PagedExtras { format, anchors: Vec::new() },
329	            )
330	        }
331	        DocumentFormat::Html => {
332	            if !engine.library.features.is_enabled(Feature::Html) {
333	                bail!(
334	                    document.span(),
335	                    "html export is only available when the `html` feature is enabled";
336	                    hint: "html export is under active development and incomplete";
337	                    hint: "to enable both bundle and html export, pass `--features bundle,html`";
338	                );
339	            }
340	
341	            let doc = typst_html::html_document_for_bundle(
342	                engine,
343	                &document.body,
344	                locator,
345	                styles,
346	            )?;
347	            BundleDocument::Html(Box::new(doc))
348	        }
349	    })
350	}
