1	use comemo::{Track, Tracked};
2	use ecow::EcoString;
3	use indexmap::IndexMap;
4	use rayon::iter::{IntoParallelRefIterator, ParallelIterator};
5	use rustc_hash::FxBuildHasher;
6	use typst_html::{HtmlElement, HtmlFormat, HtmlOptions};
7	use typst_layout::PagedDocument;
8	use typst_library::diag::{
9	    At, ParallelCollectCombinedWarnedResult, SourceResult, Warned,
10	};
11	use typst_library::format::Complete;
12	use typst_library::foundations::Bytes;
13	use typst_library::introspection::Location;
14	use typst_library::model::{Document, LateLinkResolver, PagedFormat};
15	use typst_pdf::PdfOptions;
16	use typst_render::{PngFormat, RenderOptions};
17	use typst_svg::{SvgFormat, SvgOptions};
18	use typst_syntax::{Span, VirtualPath};
19	
20	use crate::{Bundle, BundleDocument, BundleFile};
21	
22	/// A raw mapping from paths to bytes.
23	pub type VirtualFs = IndexMap<VirtualPath, Bytes, FxBuildHasher>;
24	
25	/// Exports a bundle into a raw virtual file system.
26	#[typst_macros::time(name = "export bundle")]
27	pub fn export(
28	    bundle: &Bundle,
29	    options: &BundleOptions,
30	) -> Warned<SourceResult<VirtualFs>> {
31	    bundle
32	        .files
33	        .par_iter()
34	        .map(|(path, file)| {
35	            let data = match file {
36	                BundleFile::Document(doc) => {
37	                    let link_resolver =
38	                        LateLinkResolver::new(Some(path), bundle.introspector.as_ref());
39	                    export_document(doc, options, link_resolver.track())
40	                }
41	                BundleFile::Asset(bytes) => Ok(bytes.clone()).into(),
42	            };
43	            data.map(|data| (path.clone(), data))
44	        })
45	        .collect_combined_warned_result()
46	}
47	
48	/// Settings for bundle export.
49	#[derive(Debug, Default)]
50	pub struct BundleOptions {
51	    /// Options for exporting HTML documents.
52	    pub html: HtmlOptions,
53	    /// Options for exporting PDF documents.
54	    pub pdf: PdfOptions,
55	    /// Options for exporting PNG documents.
56	    pub png: RenderOptions,
57	    /// Options for exporting SVG documents.
58	    pub svg: SvgOptions,
59	}
60	
61	/// Exports a single document.
62	fn export_document(
63	    doc: &BundleDocument,
64	    options: &BundleOptions,
65	    link_resolver: Tracked<LateLinkResolver>,
66	) -> Warned<SourceResult<Bytes>> {
67	    match doc {
68	        BundleDocument::Paged(doc, extras) => match &extras.format {
69	            PagedFormat::Pdf => {
70	                export_pdf(doc, &options.pdf, &extras.anchors, link_resolver)
71	            }
72	            PagedFormat::Png => export_png(doc, &options.png).into(),
73	            PagedFormat::Svg => {
74	                export_svg(doc, &options.svg, &extras.anchors, link_resolver).into()
75	            }
76	        },
77	        BundleDocument::Html(doc) => {
78	            let options = options.html.resolve(doc.options().get::<HtmlFormat>());
79	            export_html(doc.root(), &options, link_resolver).into()
80	        }
81	    }
82	}
83	
84	/// Exports a PDF document.
85	#[comemo::memoize]
86	#[typst_macros::time(name = "export pdf")]
87	fn export_pdf(
88	    doc: &PagedDocument,
89	    options: &PdfOptions,
90	    anchors: &[(Location, EcoString)],
91	    link_resolver: Tracked<LateLinkResolver>,
92	) -> Warned<SourceResult<Bytes>> {
93	    typst_pdf::pdf_in_bundle(doc, options, anchors, link_resolver).map(Bytes::new)
94	}
95	
96	/// Exports a PNG document.
97	#[comemo::memoize]
98	#[typst_macros::time(name = "export png")]
99	fn export_png(doc: &PagedDocument, options: &RenderOptions) -> SourceResult<Bytes> {
100	    let options = options.resolve(doc.options().get::<PngFormat>());
101	    typst_render::render(&doc.pages()[0], &options)
102	        .encode_png()
103	        .map(Bytes::new)
104	        .map_err(|_| "failed to encode PNG")
105	        .at(Span::detached())
106	}
107	
108	/// Exports an SVG document.
109	#[comemo::memoize]
110	#[typst_macros::time(name = "export svg")]
111	fn export_svg(
112	    doc: &PagedDocument,
113	    options: &SvgOptions,
114	    anchors: &[(Location, EcoString)],
115	    link_resolver: Tracked<LateLinkResolver>,
116	) -> SourceResult<Bytes> {
117	    let anchors = anchors
118	        .iter()
119	        .filter_map(|(loc, name)| {
120	            // We only support a single page at the moment and all anchor
121	            // location should point into it, so it's safe to extract just the
122	            // point using the document's introspector.
123	            let point = doc.introspector().position(*loc)?.point;
124	            Some((point, name.clone()))
125	        })
126	        .collect::<Vec<_>>();
127	    let options = options.resolve(doc.options().get::<SvgFormat>());
