        OutputFormat::Svg => export_image(document, config, ImageExportFormat::Svg)
            .at(Span::detached())
            .into(),
        OutputFormat::Html | OutputFormat::Bundle => unreachable!(),
    }
}

/// Export to a PDF.
fn export_pdf(
    document: &PagedDocument,
    config: &CompileConfig,
) -> Warned<SourceResult<()>> {
    let options = pdf_options(config);
